     1→<!DOCTYPE html>
     2→<html lang="fr" class="scroll-smooth">
     3→<head>
     4→    <meta charset="UTF-8">
     5→    <meta name="viewport" content="width=device-width, initial-scale=1.0">
     6→    <title>Comparison Lab | ChooseWisely</title>
     7→    <!-- Fonts -->
     8→    <link rel="preconnect" href="https://fonts.googleapis.com">
     9→    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    10→    <link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:ital,wght@0,100;0,200;0,300;0,400;0,500;0,600;0,700;1,100;1,200;1,300;1,400;1,500;1,600;1,700&display=swap" rel="stylesheet">
    11→    
    12→    <!-- Frameworks -->
    13→    <script src="https://unpkg.com/@tailwindcss/browser@4"></script>
    14→    <script defer src="https://unpkg.com/alpinejs@3.x.x/dist/cdn.min.js"></script>
    15→    
    16→    <style>
    17→        :root {
    18→            --brand-deep: #050810;
    19→            --brand-surface: #0D121F;
    20→            --brand-accent: #34D399; 
    21→            --brand-highlight: #6366F1;
    22→            --brand-danger: #F43F5E;
    23→            --brand-warning: #FBBF24;
    24→        }
    25→
    26→        body {
    27→            font-family: 'IBM Plex Sans', sans-serif;
    28→            background-color: var(--brand-deep);
    29→            color: #E2E8F0;
    30→            overflow-x: hidden;
    31→        }
    32→
    33→        .grain {
    34→            position: fixed;
    35→            top: 0; left: 0; width: 100%; height: 100%;
    36→            background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
    37→            opacity: 0.04;
    38→            pointer-events: none;
    39→            z-index: 9999;
    40→        }
    41→
    42→        .mesh-gradient {
    43→            background: 
    44→                radial-gradient(at 0% 0%, rgba(99, 102, 241, 0.12) 0px, transparent 50%),
    45→                radial-gradient(at 100% 0%, rgba(52, 211, 153, 0.08) 0px, transparent 50%),
    46→                radial-gradient(at 50% 100%, rgba(13, 18, 31, 1) 0px, transparent 100%);
    47→        }
    48→
    49→        .glass {
    50→            background: rgba(13, 18, 31, 0.7);
    51→            backdrop-filter: blur(12px);
    52→            border: 1px solid rgba(255, 255, 255, 0.08);
    53→        }
    54→
    55→        .matrix-cell {
    56→            border-bottom: 1px solid rgba(255, 255, 255, 0.03);
    57→            border-right: 1px solid rgba(255, 255, 255, 0.03);
    58→            transition: all 0.3s ease;
    59→        }
    60→
    61→        .best-value {
    62→            background: rgba(52, 211, 153, 0.05);
    63→            color: var(--brand-accent);
    64→            font-weight: 700;
    65→        }
    66→
    67→        .worst-value {
    68→            background: rgba(244, 63, 94, 0.05);
    69→            color: var(--brand-danger);
    70→        }
    71→
    72→        .sticky-col {
    73→            position: sticky;
    74→            left: 0;
    75→            z-index: 20;
    76→            background: var(--brand-deep);
    77→        }
    78→
    79→        /* Scanner Line Animation */
    80→        .scanner-line {
    81→            position: absolute;
    82→            left: 0;
    83→            width: 100%;
    84→            height: 1px;
    85→            background: linear-gradient(90deg, transparent, var(--brand-highlight), transparent);
    86→            box-shadow: 0 0 15px var(--brand-highlight);
    87→            z-index: 30;
    88→            pointer-events: none;
    89→            animation: scan-vertical 8s linear infinite;
    90→        }
    91→
    92→        @keyframes scan-vertical {
    93→            0% { top: 0%; opacity: 0; }
    94→            5% { opacity: 1; }
    95→            95% { opacity: 1; }
    96→            100% { top: 100%; opacity: 0; }
    97→        }
    98→
    99→        /* Custom Scrollbar */
   100→        ::-webkit-scrollbar { height: 6px; width: 6px; }
   101→        ::-webkit-scrollbar-track { background: var(--brand-deep); }
   102→        ::-webkit-scrollbar-thumb { background: #1E293B; border-radius: 10px; }
   103→        ::-webkit-scrollbar-thumb:hover { background: var(--brand-highlight); }
   104→
   105→        [x-cloak] { display: none !important; }
   106→
   107→        .decision-btn {
   108→            filter: grayscale(0.8);
   109→            transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
   110→        }
   111→        .decision-btn:hover, .decision-btn.active {
   112→            filter: grayscale(0);
   113→            transform: scale(1.1);
   114→        }
   115→    </style>
   116→</head>
   117→<body class="min-h-screen flex flex-col mesh-gradient" 
   118→      x-data="{ 
   119→        scrolled: false,
   120→        properties: [
   121→            { id: 1, title: 'Loft Industriel', city: 'Lyon 07', price: 540000, psqm: 6200, surface: 87, rooms: 3, dpe: 'C', energy: 1250, score: 88, decision: null, image: 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&q=80&w=400' },
   122→            { id: 2, title: 'Appartement Haussmannien', city: 'Lyon 06', price: 890000, psqm: 9100, surface: 98, rooms: 4, dpe: 'E', energy: 2400, score: 65, decision: 'nogo', image: 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&q=80&w=400' },
   123→            { id: 3, title: 'Maison de Ville', city: 'Villeurbanne', price: 475000, psqm: 4300, surface: 110, rooms: 5, dpe: 'B', energy: 850, score: 94, decision: 'go', image: 'https://images.unsplash.com/photo-1583608205776-bfd35f0d9f83?auto=format&fit=crop&q=80&w=400' },
   124→            { id: 4, title: 'T3 Vue Parc', city: 'Lyon 03', price: 420000, psqm: 6000, surface: 70, rooms: 3, dpe: 'D', energy: 1800, score: 72, decision: null, image: 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?auto=format&fit=crop&q=80&w=400' }
   125→        ],
   126→        removeProperty(id) {
   127→            this.properties = this.properties.filter(p => p.id !== id);
   128→        },
   129→        getBest(key, direction = 'min') {
   130→            const vals = this.properties.map(p => p[key]);
   131→            return direction === 'min' ? Math.min(...vals) : Math.max(...vals);
   132→        },
   133→        getWorst(key, direction = 'min') {
   134→            const vals = this.properties.map(p => p[key]);
   135→            return direction === 'min' ? Math.max(...vals) : Math.min(...vals);
   136→        }
   137→      }" 
   138→      @scroll.window="scrolled = (window.pageYOffset > 20)">
   139→    
   140→    <div class="grain"></div>
   141→
   142→    <!-- Header -->
   143→    <header :class="scrolled ? 'glass py-3' : 'bg-transparent py-6'" class="fixed w-full z-50 transition-all duration-500 ease-in-out">
   144→        <div class="container mx-auto px-6 flex justify-between items-center">
   145→            <div class="flex items-center gap-2">
   146→                <div class="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center font-bold text-white italic">CW</div>
   147→                <span class="text-xl font-bold tracking-tight text-white">ChooseWisely</span>
   148→            </div>
   149→            
   150→            <nav class="hidden md:flex items-center gap-8 text-sm font-medium text-slate-400">
   151→                <a href="#" class="hover:text-emerald-400 transition-colors">Recherche</a>
   152→                <a href="#" class="hover:text-emerald-400 transition-colors">Favoris</a>
   153→                <a href="#" class="text-emerald-400 font-bold border-b border-emerald-500/50">Comparison Lab</a>
   154→                <a href="#" class="hover:text-emerald-400 transition-colors">Coach</a>
   155→            </nav>
   156→
   157→            <div class="flex items-center gap-4">
   158→                <div class="flex -space-x-2">
   159→                    <img class="w-8 h-8 rounded-full border-2 border-brand-deep" src="https://i.pravatar.cc/100?u=1" alt="user">
   160→                    <img class="w-8 h-8 rounded-full border-2 border-brand-deep" src="https://i.pravatar.cc/100?u=2" alt="user">
   161→                </div>
   162→                <button class="bg-indigo-600/20 text-indigo-400 border border-indigo-500/30 px-4 py-2 rounded-full text-xs font-bold uppercase tracking-wider hover:bg-indigo-600 hover:text-white transition-all">
   163→                    Inviter un proche
   164→                </button>
   165→            </div>
   166→        </div>
   167→    </header>
   168→
   169→    <main class="flex-grow pt-32 pb-20">
   170→        <!-- Title Section -->
   171→        <section class="container mx-auto px-6 mb-12">
   172→            <div class="flex flex-col md:flex-row md:items-end justify-between gap-6">
   173→                <div>
   174→                    <div class="flex items-center gap-3 mb-4">
   175→                        <span class="w-3 h-3 rounded-full bg-emerald-500 animate-pulse"></span>
   176→                        <span class="text-xs font-bold uppercase tracking-[0.2em] text-emerald-400">Live Comparison Engine v2.4</span>
   177→                    </div>
   178→                    <h1 class="text-4xl lg:text-6xl font-bold text-white tracking-tighter">
   179→                        Comparison <span class="text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-emerald-400 italic">Lab.</span>
   180→                    </h1>
   181→                </div>
   182→                <div class="flex gap-3">
   183→                    <button class="glass px-6 py-3 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-white/5 transition-colors">
   184→                        <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
   185→                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
   186→                        </svg>
   187→                        Exporter PDF
   188→                    </button>
   189→                    <button class="bg-indigo-600 text-white px-6 py-3 rounded-xl text-sm font-bold shadow-lg shadow-indigo-500/20 hover:scale-105 transition-transform active:scale-95">
   190→                        Ajouter un bien
   191→                    </button>
   192→                </div>
   193→            </div>
   194→        </section>
   195→
   196→        <!-- Matrix Section -->
   197→        <section class="container mx-auto px-6">
   198→            <div class="glass rounded-[2.5rem] overflow-hidden border border-white/10 relative">
   199→                <div class="scanner-line"></div>
   200→                
   201→                <div class="overflow-x-auto">
   202→                    <table class="w-full border-collapse">
   203→                        <thead>
   204→                            <tr class="bg-white/[0.02]">
   205→                                <th class="sticky-col p-8 text-left min-w-[280px]">
   206→                                    <span class="text-xs font-bold text-slate-500 uppercase tracking-widest">Propriétés analysées</span>
   207→                                    <p class="text-sm text-slate-400 mt-1 font-normal italic" x-text="`${properties.length} biens en lice`"></p>
   208→                                </th>
   209→                                <template x-for="prop in properties" :key="prop.id">
   210→                                    <th class="p-6 min-w-[300px] relative group">
   211→                                        <button @click="removeProperty(prop.id)" class="absolute top-4 right-4 opacity-0 group-hover:opacity-100 p-2 bg-brand-danger/20 text-brand-danger rounded-full hover:bg-brand-danger hover:text-white transition-all z-30">
   212→                                            <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
   213→                                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12" />
   214→                                            </svg>
   215→                                        </button>
   216→                                        <div class="relative rounded-2xl overflow-hidden aspect-video mb-4 border border-white/10 group-hover:border-indigo-500/50 transition-colors">
   217→                                            <img :src="prop.image" class="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700">
   218→                                            <div class="absolute bottom-3 left-3 px-2 py-1 glass rounded-md text-[10px] font-bold text-white uppercase tracking-tighter" x-text="prop.city"></div>
   219→                                        </div>
   220→                                        <h3 class="text-lg font-bold text-white text-left truncate" x-text="prop.title"></h3>
   221→                                    </th>
   222→                                </template>
   223→                            </tr>
   224→                        </thead>
   225→                        <tbody>
   226→                            <!-- Price Row -->
   227→                            <tr>
   228→                                <td class="sticky-col p-6 matrix-cell">
   229→                                    <div class="flex items-center gap-3">
   230→                                        <div class="w-8 h-8 rounded-lg bg-indigo-500/10 flex items-center justify-center text-indigo-400">
   231→                                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 8c-1.657 0-3 1.343-3 3s1.343 3 3 3 3-1.343 3-3-1.343-3-3-3zM12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8z" /></svg>
   232→                                        </div>
   233→                                        <span class="text-sm font-semibold text-slate-300">Prix d'acquisition</span>
   234→                                    </div>
   235→                                </td>
   236→                                <template x-for="prop in properties" :key="prop.id">
   237→                                    <td class="p-6 matrix-cell text-xl font-bold italic tracking-tighter" 
   238→                                        :class="prop.price === getBest('price', 'min') ? 'best-value' : (prop.price === getWorst('price', 'min') ? 'worst-value' : '')">
   239→                                        <span x-text="prop.price.toLocaleString('fr-FR') + ' €'"></span>
   240→                                    </td>
   241→                                </template>
   242→                            </tr>
   243→
   244→                            <!-- PSQM Row -->
   245→                            <tr>
   246→                                <td class="sticky-col p-6 matrix-cell">
   247→                                    <div class="flex items-center gap-3">
   248→                                        <div class="w-8 h-8 rounded-lg bg-emerald-500/10 flex items-center justify-center text-emerald-400">
   249→                                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 6h16M4 12h16m-7 6h7" /></svg>
   250→                                        </div>
   251→                                        <span class="text-sm font-semibold text-slate-300">Prix au m²</span>
   252→                                    </div>
   253→                                </td>
   254→                                <template x-for="prop in properties" :key="prop.id">
   255→                                    <td class="p-6 matrix-cell text-lg font-medium"
   256→                                        :class="prop.psqm === getBest('psqm', 'min') ? 'best-value' : (prop.psqm === getWorst('psqm', 'min') ? 'worst-value' : '')">
   257→                                        <span x-text="prop.psqm.toLocaleString('fr-FR') + ' €/m²'"></span>
   258→                                    </td>
   259→                                </template>
   260→                            </tr>
   261→
   262→                            <!-- Surface / Rooms -->
   263→                            <tr>
   264→                                <td class="sticky-col p-6 matrix-cell">
   265→                                    <div class="flex items-center gap-3">
   266→                                        <div class="w-8 h-8 rounded-lg bg-slate-500/10 flex items-center justify-center text-slate-400">
   267→                                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>
   268→                                        </div>
   269→                                        <span class="text-sm font-semibold text-slate-300">Surface & Pièces</span>
   270→                                    </div>
   271→                                </td>
   272→                                <template x-for="prop in properties" :key="prop.id">
   273→                                    <td class="p-6 matrix-cell">
   274→                                        <div class="flex items-baseline gap-2">
   275→                                            <span class="text-lg font-bold text-white" x-text="prop.surface + 'm²'"></span>
   276→                                            <span class="text-xs text-slate-500 uppercase font-bold" x-text="prop.rooms + ' pièces'"></span>
   277→                                        </div>
   278→                                    </td>
   279→                                </template>
   280→                            </tr>
   281→
   282→                            <!-- DPE Row -->
   283→                            <tr>
   284→                                <td class="sticky-col p-6 matrix-cell">
   285→                                    <div class="flex items-center gap-3">
   286→                                        <div class="w-8 h-8 rounded-lg bg-yellow-500/10 flex items-center justify-center text-yellow-400">
   287→                                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
   288→                                        </div>
   289→                                        <span class="text-sm font-semibold text-slate-300">Classe DPE</span>
   290→                                    </div>
   291→                                </td>
   292→                                <template x-for="prop in properties" :key="prop.id">
   293→                                    <td class="p-6 matrix-cell">
   294→                                        <div class="flex items-center gap-3">
   295→                                            <div class="w-10 h-10 rounded-lg flex items-center justify-center font-black text-brand-deep" 
   296→                                                 :class="{
   297→                                                    'bg-emerald-500': ['A','B'].includes(prop.dpe),
   298→                                                    'bg-yellow-400': ['C','D'].includes(prop.dpe),
   299→                                                    'bg-rose-500': ['E','F','G'].includes(prop.dpe)
   300→                                                 }" x-text="prop.dpe"></div>
   301→                                            <div>
   302→                                                <p class="text-[10px] text-slate-500 uppercase font-bold">Conso. estimée</p>
   303→                                                <p class="text-sm font-bold text-white" x-text="prop.energy + '€ / an'"></p>
   304→                                            </div>
   305→                                        </div>
   306→                                    </td>
   307→                                </template>
   308→                            </tr>
   309→
   310→                            <!-- Confidence Score -->
   311→                            <tr>
   312→                                <td class="sticky-col p-6 matrix-cell">
   313→                                    <div class="flex items-center gap-3">
   314→                                        <div class="w-8 h-8 rounded-lg bg-pink-500/10 flex items-center justify-center text-pink-400">
   315→                                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-9.618 5.04 11.052 11.052 0 00-2.382 7.06c0 6.627 5.373 12 12 12s12-5.373 12-12c0-2.659-.863-5.115-2.382-7.06z" /></svg>
   316→                                        </div>
   317→                                        <span class="text-sm font-semibold text-slate-300">Score ChooseWisely</span>
   318→                                    </div>
   319→                                </td>
   320→                                <template x-for="prop in properties" :key="prop.id">
   321→                                    <td class="p-6 matrix-cell">
   322→                                        <div class="flex items-center gap-4">
   323→                                            <div class="text-2xl font-black italic text-white" x-text="prop.score + '%'"></div>
   324→                                            <div class="flex-grow h-1.5 bg-slate-800 rounded-full overflow-hidden">
   325→                                                <div class="h-full bg-gradient-to-r from-indigo-500 to-emerald-500" :style="`width: ${prop.score}%`"></div>
   326→                                            </div>
   327→                                        </div>
   328→                                    </td>
   329→                                </template>
   330→                            </tr>
   331→
   332→                            <!-- Decision Row -->
   333→                            <tr class="bg-white/[0.04]">
   334→                                <td class="sticky-col p-8 matrix-cell">
   335→                                    <span class="text-xs font-bold text-indigo-400 uppercase tracking-widest block mb-2">Verdict Final</span>
   336→                                    <p class="text-xs text-slate-500 leading-tight">Synchronisé avec votre partenaire</p>
   337→                                </td>
   338→                                <template x-for="prop in properties" :key="prop.id">
   339→                                    <td class="p-6 matrix-cell">
   340→                                        <div class="flex items-center gap-4">
   341→                                            <button @click="prop.decision = 'go'" 
   342→                                                    class="decision-btn w-12 h-12 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400"
   343→                                                    :class="prop.decision === 'go' ? 'active ring-4 ring-emerald-500/30 bg-emerald-500 text-brand-deep' : ''">
   344→                                                <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-width="3" d="M5 13l4 4L19 7" /></svg>
   345→                                            </button>
   346→                                            <button @click="prop.decision = 'negotiate'" 
   347→                                                    class="decision-btn w-12 h-12 rounded-2xl bg-yellow-500/10 border border-yellow-500/20 flex items-center justify-center text-yellow-400"
   348→                                                    :class="prop.decision === 'negotiate' ? 'active ring-4 ring-yellow-500/30 bg-yellow-500 text-brand-deep' : ''">
   349→                                                <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-width="2.5" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
   350→                                            </button>
   351→                                            <button @click="prop.decision = 'nogo'" 
   352→                                                    class="decision-btn w-12 h-12 rounded-2xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center text-rose-400"
   353→                                                    :class="prop.decision === 'nogo' ? 'active ring-4 ring-rose-500/30 bg-rose-500 text-brand-deep' : ''">
   354→                                                <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-width="3" d="M6 18L18 6M6 6l12 12" /></svg>
   355→                                            </button>
   356→                                        </div>
   357→                                    </td>
   358→                                </template>
   359→                            </tr>
   360→                        </tbody>
   361→                    </table>
   362→                </div>
   363→            </div>
   364→
   365→            <!-- Contextual Insights -->
